 record Destination(string Name,Vector2 Point,string Kind);
 RoadRouter carRouter=null!,walkRouter=null!;readonly MapCamera mapCamera=new();List<Destination> destinations=[];List<Destination> results=[];List<Vector2> route=[];Vector2 routeOrigin,routeTarget;bool routeDriving,searchFocus,mapWasOpen,dragged;string query="",routeStatus="";int resultOffset;Vector2 dragStart;float routeTimer;
 Rectangle MapRect=>new(24,112,Math.Max(280,GraphicsDevice.Viewport.Width-410),Math.Max(220,GraphicsDevice.Viewport.Height-190));
 float FitScale=>Math.Min(MapRect.Width/(world.Bounds[2]-world.Bounds[0]),MapRect.Height/(world.Bounds[3]-world.Bounds[1]));
