 void FitMap(){mapCamera.Center=new((world.Bounds[0]+world.Bounds[2])/2,(world.Bounds[1]+world.Bounds[3])/2);mapCamera.Scale=FitScale;}
 void InitializeNavigation(){carRouter=new(world.Roads);walkRouter=new(world.Roads,true);FitMap();
  foreach(var b in world.Buildings.Where(b=>b.Enterable)){var near=carRouter.Snap(Geo.V(b.Center)).Point;float best=float.MaxValue;Vector2 door=Geo.V(b.Center);for(int i=0;i<b.Points.Count;i++){var p=Geo.Nearest(near,Geo.V(b.Points[i]),Geo.V(b.Points[(i+1)%b.Points.Count]));float d=Vector2.DistanceSquared(p,near);if(d<best){best=d;door=p;}}var outward=door-Geo.V(b.Center);if(outward.LengthSquared()>0){outward.Normalize();door+=outward*.4f;}b.Door=door;if(b.Name.Length>0||b.Address.Length>0||b.Landmark.Length>0)destinations.Add(new(b.Label,door,"entrance"));}
  destinations.Add(new("Golden Hawk Memorial",StreetScene.GoldenHawk,"landmark"));destinations.Add(new("Lawrence House",Geo.V(world.Buildings.First(b=>b.Id==1526503538).Center),"landmark"));destinations.AddRange(landmarks.Select(l=>new Destination(l.Name,Geo.V(l.Point),"landmark")));destinations.AddRange(world.Pois.Select(p=>new Destination(p.Name,Geo.V(p.Point),p.Kind)));
  foreach(var group in world.Roads.Where(r=>r.Name.Length>0).GroupBy(r=>r.Name))destinations.Add(new(group.Key,Geo.V(group.First().Points[group.First().Points.Count/2]),"street"));
  destinations=destinations.DistinctBy(d=>(d.Name,(int)d.Point.X/25,(int)d.Point.Y/25)).OrderBy(d=>d.Name).ToList();Search();
  Window.TextInput+=(s,e)=>{if(!map||!searchFocus)return;if(e.Character=='\b'){if(query.Length>0)query=query[..^1];}else if(e.Character>=32&&e.Character<=126&&query.Length<45)query+=e.Character;Search();};
 }
 void Search(){results=destinations.Where(d=>query.Split(' ',StringSplitOptions.RemoveEmptyEntries).All(w=>(d.Name+" "+d.Kind).Contains(w,StringComparison.OrdinalIgnoreCase))).OrderBy(d=>Vector2.DistanceSquared(d.Point,OutsidePosition)).ToList();resultOffset=0;}
 void SetWaypoint(Vector2 p,string name){state.Waypoint=[p.X,p.Y];state.WaypointName=name;routeTimer=0;route=[];routeTarget=new(float.NaN);Tell("Destination: "+name);}
 void UpdateNavigation(float dt){if(!map)mapWasOpen=false;if(state.Waypoint==null)return;routeTimer-=dt;var target=Geo.V(state.Waypoint);if(routeTimer>0)return;routeTimer=1;var p=OutsidePosition;
  if(routeDriving!=driving||routeTarget!=target||Vector2.DistanceSquared(p,routeOrigin)>1600){routeDriving=driving;routeOrigin=p;routeTarget=target;route=(driving?carRouter:walkRouter).Route(p,target);routeStatus=route.Count<2?"No connected road route":"";}
 }
 void UpdateNavigationInput(KeyboardState keys,MouseState mouse){var rect=MapRect;var mp=new Vector2(mouse.X,mouse.Y);if(!mapWasOpen){mapWasOpen=true;Search();}
  if(Press(Keys.Tab,keys))searchFocus=!searchFocus;
  int wheel=mouse.ScrollWheelValue-lastMouse.ScrollWheelValue;if(wheel!=0){if(rect.Contains(mouse.X,mouse.Y))mapCamera.Zoom(mp,rect,MathF.Pow(1.25f,wheel/120f),FitScale*.6f);else resultOffset=Math.Clamp(resultOffset-wheel/120*3,0,Math.Max(0,results.Count-1));}
  if(!searchFocus){if(Press(Keys.F6,keys))TourNext();if(Press(Keys.Home,keys))FitMap();if(Press(Keys.F,keys))mapCamera.Center=OutsidePosition;if(Press(Keys.C,keys)){state.Waypoint=null;route=[];}if(Press(Keys.D,keys))SetWaypoint(Geo.V(jobs[state.Job].Point),jobs[state.Job].Destination);if(Press(Keys.T,keys))SetWaypoint(truck,"Parked truck");var pan=new Vector2((keys.IsKeyDown(Keys.Right)?1:0)-(keys.IsKeyDown(Keys.Left)?1:0),(keys.IsKeyDown(Keys.Down)?1:0)-(keys.IsKeyDown(Keys.Up)?1:0));mapCamera.Center+=pan*8/mapCamera.Scale;}
  if(searchFocus&&Press(Keys.Enter,keys)&&results.Count>resultOffset){var d=results[resultOffset];SetWaypoint(d.Point,d.Name);mapCamera.Center=d.Point;mapCamera.Scale=Math.Max(mapCamera.Scale,.8f);searchFocus=false;}
  if(mouse.LeftButton==ButtonState.Pressed&&lastMouse.LeftButton==ButtonState.Released){dragStart=mp;dragged=false;if(mp.X>rect.Right+14){if(mp.Y<155)searchFocus=true;else if(mp.Y>=205&&mp.Y<viewH-160){int i=resultOffset+(int)(mp.Y-205)/31;if(i<results.Count){var d=results[i];SetWaypoint(d.Point,d.Name);mapCamera.Center=d.Point;mapCamera.Scale=Math.Max(mapCamera.Scale,.8f);searchFocus=false;}}}}
  if(mouse.LeftButton==ButtonState.Pressed&&lastMouse.LeftButton==ButtonState.Pressed&&rect.Contains((int)dragStart.X,(int)dragStart.Y)){if(Vector2.DistanceSquared(mp,dragStart)>16)dragged=true;if(dragged)mapCamera.Center-=new Vector2(mouse.X-lastMouse.X,mouse.Y-lastMouse.Y)/mapCamera.Scale;}
  if(mouse.LeftButton==ButtonState.Released&&lastMouse.LeftButton==ButtonState.Pressed&&!dragged&&rect.Contains((int)dragStart.X,(int)dragStart.Y)&&rect.Contains(mouse.X,mouse.Y)){var p=mapCamera.World(mp,rect);if(p.X>=world.Bounds[0]&&p.X<=world.Bounds[2]&&p.Y>=world.Bounds[1]&&p.Y<=world.Bounds[3]){var nearby=destinations.MinBy(d=>Vector2.DistanceSquared(d.Point,p));if(nearby!=null&&Vector2.Distance(nearby.Point,p)*mapCamera.Scale<12)SetWaypoint(nearby.Point,nearby.Name);else SetWaypoint(p,"Custom waypoint");searchFocus=false;}}
 }
 void FitText(string s,float x,float y,int width,Color c,float scale=1){int n=Math.Max(3,(int)(width/(10*scale)));Text(s.Length>n?s[..(n-3)]+"...":s,x,y,c,scale);}
 bool ClipLine(ref Vector2 a,ref Vector2 b,Rectangle r){float lo=0,hi=1;var d=b-a;bool Bound(float p,float q){if(p==0)return q>=0;float t=q/p;if(p<0){if(t>hi)return false;lo=Math.Max(lo,t);}else{if(t<lo)return false;hi=Math.Min(hi,t);}return true;}if(!Bound(-d.X,a.X-r.Left)||!Bound(d.X,r.Right-a.X)||!Bound(-d.Y,a.Y-r.Top)||!Bound(d.Y,r.Bottom-a.Y))return false;b=a+d*hi;a+=d*lo;return true;}
 void MapLine(MapCamera camera,Rectangle rect,Vector2 a,Vector2 b,Color c,float width=1){a=camera.Screen(a,rect);b=camera.Screen(b,rect);if(ClipLine(ref a,ref b,rect))Line(a,b,c,width);}
 void Marker(MapCamera camera,Rectangle rect,Vector2 p,Color c,int size,string label=""){var q=camera.Screen(p,rect);if(!rect.Contains((int)q.X,(int)q.Y))return;Panel(new((int)q.X-size/2,(int)q.Y-size/2,size,size),c);if(label.Length>0&&q.X+size+label.Length*10<rect.Right&&q.Y+20<rect.Bottom)Text(label,q.X+size,q.Y,c,1);}
 void DrawMapRegion(MapCamera camera,Rectangle rect,bool mini){Panel(rect,new(56,71,62));var a=camera.Screen(new(world.Bounds[0],world.Bounds[1]),rect);var b=camera.Screen(new(world.Bounds[2],world.Bounds[3]),rect);var dest=Rectangle.Intersect(rect,new((int)a.X,(int)a.Y,Math.Max(1,(int)(b.X-a.X)),Math.Max(1,(int)(b.Y-a.Y))));if(dest.Width>0&&dest.Height>0){var wa=camera.World(new(dest.Left,dest.Top),rect);var wb=camera.World(new(dest.Right,dest.Bottom),rect);var na=MapPoint(wa)*1024;var nb=MapPoint(wb)*1024;var src=new Rectangle(Math.Clamp((int)na.X,0,1023),Math.Clamp((int)na.Y,0,1023),Math.Max(1,(int)(nb.X-na.X)),Math.Max(1,(int)(nb.Y-na.Y)));src=Rectangle.Intersect(src,new(0,0,1024,1024));sprites.Draw(mapTexture,dest,src,Color.White);}
  if(camera.Scale>.25f){var labels=new HashSet<string>();var labelBoxes=new List<Rectangle>();foreach(var r in world.Roads){bool visible=false;for(int i=1;i<r.Points.Count;i++){var pa=camera.Screen(Geo.V(r.Points[i-1]),rect);var pb=camera.Screen(Geo.V(r.Points[i]),rect);if(ClipLine(ref pa,ref pb,rect)){Line(pa,pb,r.Driveable?new(225,224,207):new(160,183,130),r.Driveable?2:1);visible=true;}}if(!mini&&visible&&r.Name.Length>0&&labels.Add(r.Name)){var p=camera.Screen(Geo.V(r.Points[r.Points.Count/2]),rect);var box=new Rectangle((int)p.X-5,(int)p.Y-3,r.Name.Length*9+10,25);if(rect.Contains(box)&&!labelBoxes.Any(b=>b.Intersects(box))){labelBoxes.Add(box);Panel(box,new(193,202,163,210));Text(r.Name,p.X,p.Y,new(28,35,37),.9f);}}}
   foreach(var building in world.Buildings){var center=camera.Screen(Geo.V(building.Center),rect);if(!rect.Contains((int)center.X,(int)center.Y))continue;for(int i=0;i<building.Points.Count;i++)MapLine(camera,rect,Geo.V(building.Points[i]),Geo.V(building.Points[(i+1)%building.Points.Count]),new(78,78,68));if(!mini&&camera.Scale>1.3f&&building.Enterable)Marker(camera,rect,building.Door,new(166,235,201),3);}}
  for(int i=1;i<route.Count;i++)MapLine(camera,rect,route[i-1],route[i],new(34,225,230),4);
  if(state.Waypoint!=null){var wp=Geo.V(state.Waypoint);if(route.Count>0){var from=route[^1];float length=Vector2.Distance(from,wp);for(float d=0;d<length;d+=15){var dir=length>0?(wp-from)/length:Vector2.Zero;MapLine(camera,rect,from+dir*d,from+dir*Math.Min(d+7,length),Color.Yellow,2);}}Marker(camera,rect,wp,Color.Yellow,12,mini?"":"WAYPOINT");}
  if(!mini)foreach(var l in landmarks)Marker(camera,rect,Geo.V(l.Point),Color.White,6,l.Name);
  foreach(var unit in police)Marker(camera,rect,unit.Point,new(238,91,244),7,!mini&&camera.Scale>.5f?"POLICE":"");
  if(mini||camera.Scale>.6f)foreach(var actor in traffic)Marker(camera,rect,actor.Point,Color.White,3);
  foreach(var vehicle in fleet.Where(v=>v.Id!=0))Marker(camera,rect,vehicle.Point,new(96,181,255),mini?4:6,!mini&&camera.Scale>.5f?VehicleSpec.For(vehicle.Kind).Name:"");
  if(state.JobActive)Marker(camera,rect,Geo.V(jobs[state.Job].Point),new(245,168,65),9,mini?"":"LOAD");Marker(camera,rect,truck,Color.Orange,7);Marker(camera,rect,OutsidePosition,new(245,79,75),10);var pp=camera.Screen(OutsidePosition,rect);MapLine(camera,rect,OutsidePosition,OutsidePosition+new Vector2(-MathF.Sin(yaw),-MathF.Cos(yaw))*20,Color.White,2);
  Text("N ^",rect.Left+8,rect.Top+6,Color.White,1);float metres=MathF.Pow(10,MathF.Floor(MathF.Log10(80/camera.Scale)));float bar=metres*camera.Scale;Line(new(rect.Left+10,rect.Bottom-20),new(rect.Left+10+bar,rect.Bottom-20),Color.White,2);Text(metres>=1000?$"{metres/1000:0} km":$"{metres:0} m",rect.Left+10,rect.Bottom-45,Color.White,1);
 }
 void DrawNavigationMap(){var rect=MapRect;Panel(new(0,0,viewW,viewH),new(22,39,45));Text("SARNIA / FIND YOUR WAY",24,25,new(242,206,118),2);Text("Map (C) OpenStreetMap contributors / ODbL 1.0",24,70,Color.LightGray,1);DrawMapRegion(mapCamera,rect,false);int x=rect.Right+20,w=viewW-x-20;Panel(new(x,112,w,42),searchFocus?new(69,91,86):new(39,59,62));FitText(query.Length>0?query+(searchFocus?"_":""):"Search places / streets / fuel",x+8,125,w-16,Color.White,1.1f);Text($"{results.Count} results / click to navigate",x,175,Color.LightGray,1);int rows=Math.Max(1,(viewH-365)/31);for(int i=0;i<rows&&i+resultOffset<results.Count;i++){var d=results[i+resultOffset];int y=205+i*31;Panel(new(x,y,w,29),i%2==0?new(32,50,53):new(26,44,48));FitText(d.Name,x+6,y+2,w-12,Color.White,1);FitText(d.Kind+" / "+(Vector2.Distance(d.Point,OutsidePosition)/1000).ToString("0.0")+" km",x+6,y+17,w-12,new(149,195,185),.65f);}
