 void DrawNavigationHud(){if(interior!=0){Text("Outside map available with M",viewW-330,105,Color.LightGray,1);return;}var rect=new Rectangle(viewW-290,viewH-510,265,250);Panel(new(rect.X-5,rect.Y-5,rect.Width+10,rect.Height+10),new(21,38,43));var camera=new MapCamera{Center=position,Scale=driving?.42f:.85f};DrawMapRegion(camera,rect,true);FitText(currentStreet,rect.X,rect.Bottom+8,rect.Width,Color.White,1);
  if(state.Waypoint!=null){var wp=Geo.V(state.Waypoint);float remaining=Vector2.Distance(position,wp);if(route.Count>1){float best=float.MaxValue;int index=1;Vector2 nearest=route[0];for(int i=1;i<route.Count;i++){var p=Geo.Nearest(position,route[i-1],route[i]);float d=Vector2.DistanceSquared(position,p);if(d<best){best=d;index=i;nearest=p;}}remaining=Vector2.Distance(position,nearest)+Vector2.Distance(nearest,route[index])+Vector2.Distance(route[^1],wp);for(int i=index+1;i<route.Count;i++)remaining+=Vector2.Distance(route[i-1],route[i]);}
