   if(!world.Buildings.Any(b=>b.Enterable&&Vector2.DistanceSquared(b.Door,wp)<4&&Vector2.DistanceSquared(b.Door,position)<900))WorldLabel(wp,state.WaypointName+" / "+(Vector2.Distance(position,wp)).ToString("0")+" m",Color.Yellow,Math.Max(1600,Vector2.Distance(position,wp)+1));
   var screen=GraphicsDevice.Viewport.Project(Geo.V3(wp,3),effect.Projection,effect.View,Matrix.Identity);if(screen.Z<0||screen.Z>1||screen.X<30||screen.X>viewW-30||screen.Y<100||screen.Y>viewH-240){var delta=wp-position;float bearing=MathF.Atan2(-delta.X,-delta.Y)-(yaw+(driving?cabLook:0));float x=viewW/2+Math.Clamp(MathHelper.WrapAngle(bearing)/MathHelper.Pi,-1,1)*(viewW/2-50);Text("v WAYPOINT",Math.Clamp(x-50,30,viewW-160),100,Color.Yellow,1);}}
  foreach(var b in world.Buildings.Where(b=>b.Enterable&&Vector2.DistanceSquared(b.Door,position)<900).OrderBy(b=>Vector2.DistanceSquared(b.Door,position)).Take(3)){if(!driving)WorldLabel(b.Door,"E / "+b.Label,new(178,246,212),30);}
