 void WorldLabel(Vector2 p,string label,Color color,float maximum){if(Vector2.Distance(p,position)>maximum)return;var q=GraphicsDevice.Viewport.Project(Geo.V3(p,2.8f),effect.Projection,effect.View,Matrix.Identity);if(q.Z<0||q.Z>1||q.X<20||q.X>viewW-20||q.Y<210||q.Y>viewH-240)return; // avoid labels through mapped walls
